from itertools import product
from math import comb
import sympy as sp

# Integer Smith reduction with unimodular row/column transformations: U*A*V=D.
def smith_uv(A):
    A=[list(map(int,row)) for row in A]
    m=len(A); n=len(A[0]) if m else 0
    U=[[int(i==j) for j in range(m)] for i in range(m)]
    V=[[int(i==j) for j in range(n)] for i in range(n)]
    def swap_rows(i,j):
        if i==j:return
        A[i],A[j]=A[j],A[i]; U[i],U[j]=U[j],U[i]
    def swap_cols(i,j):
        if i==j:return
        for X in (A,V):
            if X is A:
                for row in X: row[i],row[j]=row[j],row[i]
            else:
                # V is changed by right column operation
                for row in X: row[i],row[j]=row[j],row[i]
    def row_add(i,j,q): # row i += q row j
        for c in range(n): A[i][c]+=q*A[j][c]
        for c in range(m): U[i][c]+=q*U[j][c]
    def col_add(i,j,q): # col i += q col j
        for r in range(m): A[r][i]+=q*A[r][j]
        for r in range(n): V[r][i]+=q*V[r][j]
    k=0
    while k<m and k<n:
        pos=None
        for i in range(k,m):
            for j in range(k,n):
                if A[i][j] and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])):
                    pos=(i,j)
        if pos is None: break
        swap_rows(k,pos[0]); swap_cols(k,pos[1])
        while True:
            changed=True
            while changed:
                changed=False
                for i in range(k+1,m):
                    if A[i][k]:
                        q=A[i][k]//A[k][k]
                        row_add(i,k,-q)
                        if A[i][k]: swap_rows(i,k)
                        changed=True; break
                if changed: continue
                for j in range(k+1,n):
                    if A[k][j]:
                        q=A[k][j]//A[k][k]
                        col_add(j,k,-q)
                        if A[k][j]: swap_cols(j,k)
                        changed=True; break
            bad=None
            p=A[k][k]
            for i in range(k+1,m):
                for j in range(k+1,n):
                    if A[i][j] % p:
                        bad=(i,j); break
                if bad: break
            if bad is None: break
            # introduce a nondivisible trailing entry into pivot row
            row_add(k,bad[0],1)
        if A[k][k]<0:
            row_add(k,k,-2) # negate row k
        k+=1
    return A,U,V

def parts(d,maxrows,maxpart,cap=None):
    out=[]
    def rec(rem,last,cur):
        if rem==0:
            out.append(tuple(cur)); return
        if cap is not None and len(cur)>=cap:return
        for x in range(min(last,rem),0,-1): rec(rem-x,x,cur+[x])
    rec(d,maxpart,[])
    return [p for p in out if len(p)<=maxrows]

def all_parts(r,k):
    D={}
    for d in range(r*k+1): D[d]=parts(d,r,k)
    return D

def contains(big,small):
    return all((big[q] if q<len(big) else 0)>=(small[q] if q<len(small) else 0) for q in range(max(len(big),len(small))))
def hmul(lam,e,bydeg):
    ans=[]
    for nu in bydeg[sum(lam)+e]:
        # nu/lam horizontal iff nu_1>=lam_1>=nu_2>=lam_2>=...
        if not contains(nu,lam): continue
        ok=True
        L=max(len(lam),len(nu))
        for q in range(L):
            la=lam[q] if q<len(lam) else 0
            nxt=nu[q+1] if q+1<len(nu) else 0
            if la<nxt: ok=False; break
        if ok: ans.append(nu)
    return ans

def colbasis(C):
    # C lists columns (equal length); return a Z-basis of their column lattice.
    if not C:return []
    M=[[C[j][i] for j in range(len(C))] for i in range(len(C[0]))]
    D,U,V=smith_uv(M)
    rank=sum(1 for q in range(min(len(D),len(D[0]))) if D[q][q])
    Ui=sp.Matrix(U).inv()
    return [[int(D[q][q])*int(Ui[i,q]) for i in range(len(M))] for q in range(rank)]

def invariants_for(r,k,i,j,which):
    bydeg=all_parts(r,k); idx={d:{p:q for q,p in enumerate(bydeg[d])} for d in bydeg}
    a=min(k-i,r-j); b=min(i,j); N=comb(a+b,a)
    low=(i,)*j
    if which==1: upper=(i+a,)*b+(i,)*(j-b)
    else: upper=(i,)*j+(b,)*a
    G={d:[] for d in bydeg}
    for d,ps in bydeg.items():
        for p in ps:
            if contains(p,low) and contains(upper,p):
                v=[0]*len(ps);v[idx[d][p]]=1;G[d].append(v)
    Jbasis={}; allinv=[]
    for d in range(r*k+1):
        L=[]
        for q in range(d):
            for vec in Jbasis.get(q,[]):
                for e in [d-q]:
                    w=[0]*len(bydeg[d])
                    for z,c in enumerate(vec):
                        if c:
                            for nu in hmul(bydeg[q][z],e,bydeg): w[idx[d][nu]]+=c
                    L.append(w)
        C=L+G[d]
        Jbasis[d]=colbasis(C)
        # Relations among degree-d original generators modulo L.
        g=len(G[d]); ell=len(L)
        if g:
            A=[]
            for row in range(len(bydeg[d])):
                A.append([G[d][z][row] for z in range(g)]+[-L[z][row] for z in range(ell)])
            D,U,V=smith_uv(A)
            rk=sum(1 for z in range(min(len(D),len(D[0]))) if D[z][z])
            ker=[]
            for c in range(rk,len(V)):
                ker.append([V[z][c] for z in range(g)])
            if ker:
                R=[[ker[c][row] for c in range(len(ker))] for row in range(g)]
                E,_,_=smith_uv(R)
                rr=sum(1 for z in range(min(len(E),len(E[0]))) if E[z][z])
                allinv += [abs(E[z][z]) for z in range(rr) if abs(E[z][z])>1]
                free=g-rr
            else: free=g
            # Each degree is independent in the graded quotient.
            allinv += [0]*free
    rank=sum(q==0 for q in allinv); tors=sorted(q for q in allinv if q>1)
    mu=rank+(max([0]+[sum(1 for q in tors if q%p==0) for p in range(2,(max(tors) if tors else 1)+1) if all(p%d for d in range(2,int(p**.5)+1))]))
    return a,b,N,rank,tors,mu

cases=[('boundary',4,5,2,2),('outside-smallest-r',5,1,1,1),('outside-smallest-k',1,6,1,1),('outside-nontrivial-r',5,2,1,3),('outside-nontrivial-k',2,6,3,1)]
print('case r k i j | set | a b N | rank torsion-invariant-factors mu | mu=N')
for name,r,k,i,j in cases:
    for w in (1,2):
        a,b,N,rank,tors,mu=invariants_for(r,k,i,j,w)
        print(f'{name:22s} {r} {k} {i} {j} | {w} | {a} {b} {N} | {rank} {tors if tors else "[]"} {mu} | {mu==N}')
